var ErrActivityPaused = go.temporal.io/sdk/internal.ErrActivityPaused // ErrActivityPaused is returned from an activity heartbeat or the cause of an activity's context to indicate that the activity is paused.
//
// WARNING: Activity pause is currently experimental

var ErrActivityReset = go.temporal.io/sdk/internal.ErrActivityReset // ErrActivityReset is returned from an activity heartbeat or the cause of an activity's context to indicate that the activity has been reset.
//
// WARNING: Activity reset is currently experimental

var ErrResultPending = go.temporal.io/sdk/internal.ErrActivityResultPending // ErrResultPending is returned from activity's implementation to indicate the activity is not completed when the
// activity method returns. Activity needs to be completed by Client.CompleteActivity() separately. For example, if an
// activity requires human interaction (like approving an expense report), the activity could return ErrResultPending,
// which indicates the activity is not done yet. Then, when the waited human action happened, it needs to trigger something
// that could report the activity completed event to the temporal server via the Client.CompleteActivity() API.

struct {
	ActivityID string // ActivityID is the ID of the activity.
}

struct {
	ActivityRunID string // ActivityRunID is the run ID of the activity. Empty if the activity was started by a workflow.
}

struct {
	Name string // Name is the name of the activity type.
}

struct {
	ActivityType ActivityType // ActivityType is the type of the activity.
}

struct {
	Attempt int32 // Attempt starts from 1, and increased by 1 for every retry if retry policy is specified.
}

struct {
	Deadline time.Time // Deadline is the time of activity timeout.
}

struct {
	HeartbeatTimeout time.Duration // HeartbeatTimeout is the maximum time between heartbeats. 0 means no heartbeat needed.
}

struct {
	IsLocalActivity bool // IsLocalActivity is true if it is a local activity.
}

struct {
	Namespace string // Namespace is the namespace of this activity.
}

struct {
	FairnessKey string // FairnessKey is a short string that's used as a key for a fairness
	// balancing mechanism. It may correspond to a tenant id, or to a fixed
	// string like "high" or "low". The default is the empty string.
	//
	// The fairness mechanism attempts to dispatch tasks for a given key in
	// proportion to its weight. For example, using a thousand distinct tenant
	// ids, each with a weight of 1.0 (the default) will result in each tenant
	// getting a roughly equal share of task dispatch throughput.
	//
	// Fairness keys are limited to 64 bytes.
}

struct {
	FairnessWeight float32 // FairnessWeight for a task can come from multiple sources for
	// flexibility. From highest to lowest precedence:
	// 1. Weights for a small set of keys can be overridden in task queue
	//    configuration with an API.
	// 2. It can be attached to the workflow/activity in this field.
	// 3. The default weight of 1.0 will be used.
	//
	// Weight values are clamped to the range [0.001, 1000].
}

struct {
	PriorityKey int // PriorityKey is a positive integer from 1 to n, where smaller integers
	// correspond to higher priorities (tasks run sooner). In general, tasks in
	// a queue should be processed in close to priority order, although small
	// deviations are possible.
	//
	// The maximum priority value (minimum priority) is determined by server
	// configuration, and defaults to 5.
	//
	// The default value when unset or 0 is calculated by (min+max)/2. With the
	// default max of 5, and min of 1, that comes out to 3.
}

struct {
	Priority Priority // Priority settings that control relative ordering of task processing when activity tasks are backed up in a queue.
	// If no priority is set, the default value is the zero value.
	//
	// WARNING: Task queue priority is currently experimental.
}

struct {
	BackoffCoefficient float64 // Coefficient used to calculate the next retry backoff interval.
	// The next retry interval is previous interval multiplied by this coefficient.
	// Must be 1 or larger. Default is 2.0.
}

struct {
	InitialInterval time.Duration // Backoff interval for the first retry. If BackoffCoefficient is 1.0 then it is used for all retries.
	// If not set or set to 0, a default interval of 1s will be used.
}

struct {
	MaximumAttempts int32 // Maximum number of attempts. When exceeded the retries stop even if not expired yet.
	// If not set or set to 0, it means unlimited, and rely on activity ScheduleToCloseTimeout to stop.
}

struct {
	MaximumInterval time.Duration // Maximum backoff interval between retries. Exponential backoff leads to interval increase.
	// This value is the cap of the interval. Default is 100x of initial interval.
}

struct {
	NonRetryableErrorTypes [ // Non-Retriable errors. This is optional. Temporal server will stop retry if error type matches this list.
	//
	// Note:
	//  - cancellation is not a failure, so it won't be retried,
	//  - only StartToClose or Heartbeat timeouts are retryable.
	]string
}

struct {
	RetryPolicy *RetryPolicy // Retry policy for the activity. Note that the server may have set a different policy than the one provided
	// when scheduling the activity. If the value is nil, it means the server didn't send information about
	// retry policy (e.g. due to old server version), but it may still be defined server-side.
}

struct {
	ScheduleToCloseTimeout time.Duration // ScheduleToCloseTimeout is the schedule to close timeout set by the activity options.
}

struct {
	ScheduledTime time.Time // ScheduledTime is the time when the activity was scheduled by a workflow.
}

struct {
