ActivityExecutionOptions = go.temporal.io/sdk/internal.ClientActivityExecutionOptions // ActivityExecutionOptions describes the options an activity is currently running with, as
// returned by ActivityHandle.UpdateOptions and ActivityHandle.RestoreOriginalOptions.
//
// NOTE: Experimental

struct {
	Cancel func(ctx context.Context, options ClientCancelActivityOptions) error // Cancel requests cancellation of the activity.
}

struct {
	Describe func(ctx context.Context, options ClientDescribeActivityOptions) (*ClientActivityExecutionDescription, error) // Describe returns detailed information about current state of the activity execution.
}

struct {
	Get func(ctx context.Context, valuePtr any) error // Get waits until the activity finishes and gets its result. If the activity completes successfully, the result
	// is written to valuePtr and nil is returned. If the activity failed, the failure is returned as an error.
	// If an error is encountered trying to get the activity result, that error is returned.
}

struct {
	GetID func() string // GetID returns the ID of the activity this handle points to.
}

struct {
	GetRunID func() string // GetRunID returns the run ID that this handle was created with.
	//
	// Handle returned by [client.Client] has it set to run ID of the started execution.
	//
	// Handle returned by client.Client.GetActivityHandle has it set to the provided run ID.
	// If empty run ID was provided, then this function returns empty string and the handle points to the most
	// recent execution with matching activity ID. The run ID of this execution can be retrieved by calling Describe.
}

struct {
	Pause func(ctx context.Context, options ClientPauseActivityOptions) error // Pause pauses the activity. A paused activity stops being retried and, if an attempt is
	// currently running, that attempt is asked to yield. Pausing an already-paused activity
	// is a no-op.
	//
	// NOTE: Experimental
}

struct {
	RestoreOriginalOptions func(ctx context.Context) (*ClientActivityExecutionOptions, error) // RestoreOriginalOptions reverts every option changed by UpdateOptions back to the value
	// the activity was scheduled with, and returns the restored options. It is a separate
	// call because the server does not allow the restore flag to be combined with any
	// individual option change.
	//
	// NOTE: Experimental
}

struct {
	Terminate func(ctx context.Context, options ClientTerminateActivityOptions) error // Terminate terminates the activity.
}

struct {
	Unpause func(ctx context.Context, options ClientUnpauseActivityOptions) error // Unpause resumes a paused activity. Unpausing an activity that is not paused is a no-op.
	//
	// NOTE: Experimental
}

struct {
	UpdateOptions func(ctx context.Context, update ClientActivityOptionsUpdate) (*ClientActivityExecutionOptions, error) // UpdateOptions changes some of the activity's options, leaving the rest untouched, and
	// returns the options as they stand after the update. At least one change must be set.
	//
	// NOTE: Experimental
}

