			Start: 12,
		}},
		DayOfMonth: []ScheduleRange{
			{
				Start: 1,
				End:   31,
			},
		},
		Month: []ScheduleRange{
			{
				Start: 1,
				End:   12,
			},
		},
		DayOfWeek: []ScheduleRange{
