struct {
	Add func(delta int) // Add adds delta, which may be negative, to the WaitGroup task counter.
	// If the counter becomes zero, all goroutines blocked on WaitGroup.Wait are released.
	// If the counter goes negative, Add panics.
	//
	// Callers should prefer WaitGroup.Go.
}

struct {
	Done func() // Done decrements the WaitGroup task counter by one.
	// It is equivalent to Add(-1).
	//
	// Callers should prefer WaitGroup.Go.
}

struct {
	Go func(ctx Context, f func(Context)) // Go calls f in a new goroutine and adds that task to the WaitGroup.
	// When f returns, the task is removed from the WaitGroup.
}

struct {
	Wait func(ctx Context) // Wait blocks and waits for specified number of coroutines to
	// finish executing and then unblocks once the counter has reached 0.
}

